import{_ as e,o as a,c as l,a5 as n}from"./chunks/framework.Cooo9kuv.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"799-批量检测图片尺寸-将名称标注尺寸与实际不符的文件路径写入txt中","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["图片批处理"],"标签":["图片实际尺寸检测","检测图片的实际尺寸"]},"headers":[{"level":3,"title":"程序介绍","slug":"程序介绍","link":"#程序介绍","children":[]},{"level":3,"title":"如下图所示","slug":"如下图所示","link":"#如下图所示","children":[]},{"level":3,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":3,"title":"输出的txt文档效果展示","slug":"输出的txt文档效果展示","link":"#输出的txt文档效果展示","children":[]},{"level":3,"title":"支持的图片文件格式","slug":"支持的图片文件格式","link":"#支持的图片文件格式","children":[]},{"level":3,"title":"是否支持子文件夹穿透","slug":"是否支持子文件夹穿透","link":"#是否支持子文件夹穿透","children":[]},{"level":3,"title":"使用前配置","slug":"使用前配置","link":"#使用前配置","children":[]}],"relativePath":"md/图片批处理/799-批量检测图片尺寸-将名称标注尺寸与实际不符的文件路径写入txt中.md","filePath":"md/图片批处理/799-批量检测图片尺寸-将名称标注尺寸与实际不符的文件路径写入txt中.md"}'),o={name:"md/图片批处理/799-批量检测图片尺寸-将名称标注尺寸与实际不符的文件路径写入txt中.md"};function r(i,t,s,p,h,_){return a(),l("div",null,[...t[0]||(t[0]=[n('<h3 id="程序介绍" tabindex="-1">程序介绍 <a class="header-anchor" href="#程序介绍" aria-label="Permalink to &quot;程序介绍&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250422220445174533068594260.png" alt=""></p><p>批量检测指定文件夹下图片名中的尺寸是否与图片实际尺寸一致，将不一致的图片路径及图片名写入到txt文档中，txt文档会保存在输入的文件夹路径下。</p><p><strong>图片文件中的尺寸格式为：</strong></p><p>1、文档1 软膜 高2860mm宽1200mm.jpg，需要在文件名中存在宽、高数据</p><p>2、如果没有宽高数据，或只有宽或高数据则会写入到txt文档中</p><h3 id="如下图所示" tabindex="-1">如下图所示 <a class="header-anchor" href="#如下图所示" aria-label="Permalink to &quot;如下图所示&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250422233402174533604266754.jpg" alt=""></p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p>尺寸单位使用的是 mm 单位，正确的尺寸不会出现在txt文档中，只有实际尺寸与文件名中标注的尺寸不匹配时才会写入到txt文档中</p><h3 id="输出的txt文档效果展示" tabindex="-1">输出的txt文档效果展示 <a class="header-anchor" href="#输出的txt文档效果展示" aria-label="Permalink to &quot;输出的txt文档效果展示&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250422220803174533088348834.jpg" alt=""></p><h3 id="支持的图片文件格式" tabindex="-1">支持的图片文件格式 <a class="header-anchor" href="#支持的图片文件格式" aria-label="Permalink to &quot;支持的图片文件格式&quot;">​</a></h3><p>&#39;.jpg&#39;, &#39;.jpeg&#39;, &#39;.png&#39;, &#39;.bmp&#39;, &#39;.gif&#39;, &#39;.tiff&#39;, &#39;.tif&#39;,&#39;.webp&#39;, &#39;.psd&#39;, &#39;.heic&#39;, &#39;.heif&#39;</p><h3 id="是否支持子文件夹穿透" tabindex="-1">是否支持子文件夹穿透 <a class="header-anchor" href="#是否支持子文件夹穿透" aria-label="Permalink to &quot;是否支持子文件夹穿透&quot;">​</a></h3><p>支持子文件夹穿透</p><h3 id="使用前配置" tabindex="-1">使用前配置 <a class="header-anchor" href="#使用前配置" aria-label="Permalink to &quot;使用前配置&quot;">​</a></h3><p>需要将 apitool 文件夹复制或剪切到C盘根目录下</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1727.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1727.html</a></p>',20)])])}const g=e(o,[["render",r]]);export{d as __pageData,g as default};
